import React from 'react'
import ErrorComponent from './Error'

type ErrorBoundaryState = {
  showErrorComponent: boolean
  hasError: boolean // 是否发生错误
  retryCount: number // 错误重试计数
}

const MAX_RETRY_COUNT = 1
export default class ErrorBoundary extends React.Component<object, ErrorBoundaryState> {
  constructor(props: any) {
    super(props)
    this.state = {
      showErrorComponent: false,
      hasError: false,
      retryCount: 0
    }
  }

  // 获取 URL 中的重试次数
  getRetryCountFromURL(): number {
    const params = new URLSearchParams(window.location.search)
    const retryCount = parseInt(params.get('retryCount') || '0', 10)
    return retryCount
  }

  // 更新 URL 中的重试次数
  updateRetryCountInURL(newRetryCount: number) {
    const params = new URLSearchParams(window.location.search)

    // 设置新的重试次数
    params.set('retryCount', newRetryCount.toString())

    // 保持其他 URL 参数不变，更新 URL
    window.history.replaceState(null, '', `${window.location.pathname}?${params.toString()}`)
  }

  static getDerivedStateFromError(error: any) {
    // 更新状态以便下次渲染可以显示备用 UI
    return { hasError: true, showErrorComponent: false }
  }

  componentDidCatch(error: any, errorInfo: any) {
    // 可以在这里记录错误信息
    console.error('Error caught in Error Boundary: ', error, errorInfo)

    const isFetchResError = error && String(error).includes('Failed to fetch dynamically imported module')
    if (isFetchResError) {
      // 获取当前的重试次数
      const currentRetryCount = this.getRetryCountFromURL()

      if (currentRetryCount < MAX_RETRY_COUNT) {
        // 增加重试次数
        const newRetryCount = currentRetryCount + 1
        this.updateRetryCountInURL(newRetryCount)

        console.log(`Retrying... (${newRetryCount}/${MAX_RETRY_COUNT})`)
        window.location.reload()
      } else {
        console.error('Max retry count reached. Showing fallback UI.')
        this.setState({ showErrorComponent: true, hasError: true })
      }
    } else {
      this.setState({ showErrorComponent: true, hasError: true })
    }
  }

  render() {
    if ((this.state as any).hasError) {
      if (this.state.showErrorComponent) {
        return <ErrorComponent />
      }
      return <></>
    }

    return (this.props as any).children
  }
}
